import type { Post } from "./types";
import { externalPosts } from "../data/external";

export function listExternalPosts(): Post[] {
  // Generated by src/scripts/fetch-bengo4.ts and gitignored, so the file
  // may be absent (fresh clone, CI); glob yields {} in that case
  const generated = import.meta.glob<Post[]>("../data/generated/bengo4.json", {
    eager: true,
    import: "default",
  });

  // Combine RSS-generated + manually curated external posts
  return [...Object.values(generated).flat(), ...externalPosts];
}
